import express, { ErrorRequestHandler, Request, Response, Router } from "express";
import type { CatalogueService } from "../application/catalogue-service";
import type { OrderService } from "../application/order-service";
import {
  DomainError,
  InsufficientStockError,
  InvalidTransitionError,
  NotFoundError,
  ValidationError,
} from "../domain/errors";
import { isOrderState, ORDER_STATES, OrderState } from "../domain/order";

export interface Services {
  catalogue: CatalogueService;
  orders: OrderService;
}

/** Action endpoints that move an order to a specific state. */
const ACTIONS: Readonly<Record<string, OrderState>> = {
  pay: "paid",
  pack: "packed",
  ship: "shipped",
  deliver: "delivered",
  cancel: "cancelled",
};

export function createApp(services: Services): express.Express {
  const app = express();
  app.use(express.json());

  app.get("/health", (_req: Request, res: Response) => {
    res.json({ status: "ok" });
  });

  app.use("/products", productRoutes(services.catalogue));
  app.use("/orders", orderRoutes(services.orders));

  app.use((_req: Request, res: Response) => {
    res.status(404).json({ error: { code: "NOT_FOUND", message: "Route not found" } });
  });
  app.use(errorHandler);

  return app;
}

function productRoutes(catalogue: CatalogueService): Router {
  const router = Router();

  // Staff view of stock levels for every product.
  router.get("/", (_req: Request, res: Response) => {
    res.json(catalogue.listProducts());
  });

  router.get("/:id", (req: Request, res: Response) => {
    res.json(catalogue.getProduct(param(req, "id")));
  });

  router.post("/", (req: Request, res: Response) => {
    const body = asObject(req.body);
    const product = catalogue.addProduct({
      id: requireString(body, "id"),
      name: requireString(body, "name"),
      priceCents: requireNumber(body, "priceCents"),
      stock: requireNumber(body, "stock"),
    });
    res.status(201).json(product);
  });

  return router;
}

function orderRoutes(orders: OrderService): Router {
  const router = Router();

  router.post("/", (req: Request, res: Response) => {
    const body = asObject(req.body);
    const rawItems = body["items"];
    if (!Array.isArray(rawItems)) throw new ValidationError("items must be an array");
    const items = rawItems.map((raw: unknown, i: number) => {
      const item = asObject(raw, `items[${i}]`);
      return {
        productId: requireString(item, "productId", `items[${i}].productId`),
        quantity: requireNumber(item, "quantity", `items[${i}].quantity`),
      };
    });
    const order = orders.placeOrder({ customerId: requireString(body, "customerId"), items });
    res.status(201).json(order);
  });

  // Staff listing, optionally filtered: GET /orders?state=paid
  router.get("/", (req: Request, res: Response) => {
    const state = req.query["state"];
    if (state === undefined) {
      res.json(orders.listOrders());
      return;
    }
    if (!isOrderState(state)) {
      throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
    }
    res.json(orders.listOrders(state));
  });

  router.get("/:id", (req: Request, res: Response) => {
    res.json(orders.getOrder(param(req, "id")));
  });

  // Generic transition: PATCH /orders/:id { "state": "paid" }
  router.patch("/:id", (req: Request, res: Response) => {
    const state = asObject(req.body)["state"];
    if (!isOrderState(state)) {
      throw new ValidationError(`state must be one of: ${ORDER_STATES.join(", ")}`);
    }
    res.json(orders.transition(param(req, "id"), state));
  });

  // Convenience actions: POST /orders/:id/pay | pack | ship | deliver | cancel
  router.post("/:id/:action", (req: Request, res: Response) => {
    const target = ACTIONS[param(req, "action")];
    if (!target) throw new NotFoundError(`Unknown action ${param(req, "action")}`);
    res.json(orders.transition(param(req, "id"), target));
  });

  return router;
}

const errorHandler: ErrorRequestHandler = (err: unknown, _req, res, _next) => {
  if (err instanceof DomainError) {
    res.status(statusFor(err)).json({ error: { code: err.code, message: err.message } });
    return;
  }
  if (isBodyParseError(err)) {
    res.status(400).json({ error: { code: "INVALID_JSON", message: "Request body is not valid JSON" } });
    return;
  }
  console.error(err);
  res.status(500).json({ error: { code: "INTERNAL_ERROR", message: "Internal server error" } });
};

function statusFor(err: DomainError): number {
  if (err instanceof ValidationError) return 400;
  if (err instanceof NotFoundError) return 404;
  if (err instanceof InsufficientStockError) return 409;
  if (err instanceof InvalidTransitionError) return 409;
  return 400;
}

function isBodyParseError(err: unknown): boolean {
  return typeof err === "object" && err !== null && (err as { type?: unknown }).type === "entity.parse.failed";
}

function param(req: Request, name: string): string {
  const value: unknown = (req.params as Record<string, unknown>)[name];
  if (typeof value !== "string") throw new ValidationError(`Missing path parameter ${name}`);
  return value;
}

function asObject(value: unknown, label = "body"): Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new ValidationError(`${label} must be a JSON object`);
  }
  return value as Record<string, unknown>;
}

function requireString(obj: Record<string, unknown>, key: string, label = key): string {
  const value = obj[key];
  if (typeof value !== "string" || !value.trim()) throw new ValidationError(`${label} must be a non-empty string`);
  return value;
}

function requireNumber(obj: Record<string, unknown>, key: string, label = key): number {
  const value = obj[key];
  if (typeof value !== "number" || !Number.isFinite(value)) throw new ValidationError(`${label} must be a number`);
  return value;
}

